// Evento de la API al confirmar una propuesta (solo identificadores, códigos y montos: sin PII).
const e = $json.body;
const p = e.parametros || {};
const r = e.resultado || {};
const ERP = 'http://erp-mock:8083/v1';
const salida = [];
// POL-RET-2026: la visita técnica prioritaria (ticket a nivel 2) se programa como orden de servicio en 24 h.
if (e.accion === 'crearTicket' && p.categoria === 'soporte_tecnico' && p.escalar_a === 'nivel2') {
  salida.push({ json: { destino: 'Orden de servicio (visita técnica)', url: `${ERP}/ordenes-servicio`,
    cuerpo: { cliente_id: e.cliente_id, tipo: 'visita_tecnica',
              prioridad: p.prioridad === 'prioritaria' ? 'prioritaria' : 'estandar', ticket_id: r.ticket_id } } });
}
// Ajuste de factura → nota crédito en contabilidad (idempotente por ajuste_id: el ERP rechaza duplicados).
if (e.accion === 'aplicarAjuste' && r.ajuste_id) {
  salida.push({ json: { destino: 'Nota crédito', url: `${ERP}/notas-credito`,
    cuerpo: { factura_id: p.factura_id, cliente_id: e.cliente_id, valor: p.valor, ajuste_id: r.ajuste_id,
              motivo: `Ajuste ${r.ajuste_id} confirmado en Copiloto por ${e.confirmada_por} (${e.rol})` } } });
}
return salida; // otras acciones (oferta de retención, tickets comunes) no requieren ERP
